# Motor Control Client in python
import matplotlib.pyplot as plt
from statistics import mean

def read_plot_matrix(data, window=5):
    # Extract the second value from each data tuple.
    values = [y for _, y in data]

    # Compute a simple moving average over the second tuple values.
    filtered = [
        mean(values[max(0, i - window + 1): i + 1])
        for i in range(len(values))
    ]

    t = range(len(values))
    plt.plot(t, values, 'r*-', label='raw second value')
    plt.plot(t, filtered, 'b-', label=f'{window}-point moving average')
    plt.ylabel('value')
    plt.xlabel('index')
    plt.legend()
    plt.show()


